// misalnya array pointer ke bitmap
const uint8_t* rabbitFrames[6] = {RABBIT1, RABBIT2, RABBIT3, RABBIT4, RABBIT5, RABBIT6};

void DisplayRabbitAnimation(void) {
    for (int iter = 0; iter < 4; iter++) {          // 10 kali iterasi
        for (int frame = 0; frame < 6; frame++) {    // 6 frame per iterasi
            u8g2_ClearBuffer(&display);
            u8g2_SetBitmapMode(&display, 1);
            u8g2_SetFontMode(&display, 1);

            u8g2_DrawXBM(&display, 0, 0, 64, 64, rabbitFrames[frame]);
            u8g2_SetFont(&display, u8g2_font_6x12_tr);
            u8g2_DrawStr(&display, 61, 27, "bunny");
            u8g2_DrawStr(&display, 61, 38, "is running");
            u8g2_DrawStr(&display, 61, 48, "...");

            u8g2_SendBuffer(&display);

            HAL_Delay(25);

        }
    }
}

//Menyederhanakan perintah LCD
void lcd_print_unit(uint8_t col, uint8_t row, uint16_t data, UnitLcd_e unit) {
	switch (unit) {
		case UNIT_VOLTAGE: // Print unit Tegangan
			sprintf(lcd_buff, "%u.%01uV ", data / 10, data % 10);
			break;
		case UNIT_CURRENT: // Print unit Arus
			sprintf(lcd_buff, "%u.%01uA ", data / 10, data % 10);
			break;
		case UNIT_TEMPERATURE: // Print unit Suhu
			sprintf(lcd_buff, "%d%cC ", data, 0xB0);
			break;
		case UNIT_PERCENTAGE: // Print unit Persen
			sprintf(lcd_buff, "%d%%", data);
			break;
		case UNIT_POWER: // Print unit Daya
			sprintf(lcd_buff, "%u.%01uW ", data / 100, data % 100);
			break;
		default:
			break;
	}
	u8g2_DrawStr(&display, col, row, lcd_buff);
	//memset(lcd_buff, 0, sizeof(lcd_buff));
}

void lcd_main_display() {
	u8g2_ClearBuffer(&display);
	u8g2_DrawFrame(&display, 0, 0, 128, 64);

	u8g2_DrawXBM(&display, 10, 2, 15, 12, PV_CHAR);
	u8g2_DrawXBM(&display, 56, 2, 16, 12, MPPT_CHAR);
	u8g2_DrawXBM(&display, 103, 2, 15, 12, BAT_CHAR);

	u8g2_SetFont(&display, u8g2_font_6x10_tf);

	lcd_print_unit(2, 23, dis_voltage_pv, UNIT_VOLTAGE);
	lcd_print_unit(97, 23, dis_voltage_bat, UNIT_VOLTAGE);
	lcd_print_unit(2, 34, dis_current_pv, UNIT_CURRENT);
	lcd_print_unit(97, 34, dis_current_bat, UNIT_CURRENT);
	lcd_print_unit(53, 23, dis_temperature, UNIT_TEMPERATURE);
	lcd_print_unit(53, 34, duty_percent, UNIT_PERCENTAGE);
	lcd_print_unit(2, 45, dis_power_pv, UNIT_POWER);
	lcd_print_unit(91, 45, dis_power_bat, UNIT_POWER);
	lcd_print_unit(97, 56, soc_battery, UNIT_PERCENTAGE);


	if(flag_charging_Bulk) {
		u8g2_DrawStr(&display, 2, 56, "MPPT MODE >.<");
	} else if (flag_charging_CV) {
		u8g2_DrawStr(&display, 2, 56, "ABSORP/CV MODE");
	} else if (flag_charging_FLOAT) {
		u8g2_DrawStr(&display, 2, 56, "FLOAT MODE ^o^");
	} else {
		u8g2_DrawStr(&display, 2, 56, "STANDBY (^///^)");
	}



	u8g2_SendBuffer(&display);
}
